# shellcheck shell=bash disable=SC2034
# i18n.sh — gdmount interface translations.
# Source strings are in Ukrainian (printf formats used by install.sh); GDMOUNT_EN has the English texts.
# Every message is looked up by its exact text, so there is no partial-word replacement.
#
# SPDX-License-Identifier: MIT
# Copyright (C) 2026 Pan Vena

gdmount_detect_lang() {
  local v
  for v in "${LC_ALL:-}" "${LC_MESSAGES:-}" "${LANG:-}"; do
    [[ -n "$v" ]] || continue
    [[ "${v,,}" == uk* ]] && echo uk || echo en
    return 0
  done
  echo en
}

_() {
  local s="$1"; shift
  if [[ "${GDMOUNT_UI_LANG:-uk}" == en && -n "${GDMOUNT_EN[$s]+x}" ]]; then
    s="${GDMOUNT_EN[$s]}"
  fi
  if (($#)); then printf -- "$s" "$@"; else printf '%s' "$s"; fi
}

